﻿<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">

<html xmlns="http://www.w3.org/1999/xhtml" lang="ko">
<head>
    <title>딜로이트 채용</title>
    <meta charset="UTF-8">
	<meta name="description" content="안진회계법인, 컨설팅, 그 외 법인 채용정보 및 온라인 입사 지원서 작성 안내"/>
	<meta name="naver-site-verification" content="d275625bcb6e7f9afd6ee35018ad0c38514c75c4"/>
	<meta name="viewport" content="user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0, width=device-width" />
    <link rel="icon" type="image/vnd.microsoft.icon" href="favicon.ico" />
    <link rel="shortcut icon" type="image/vnd.microsoft.icon" href="favicon.ico" />
    <script src="/WiseRecruit2/Common/Js/jquery-3.6.0.min.js" type="text/javascript"></script>
    <script src="/WiseRecruit2/Common/Js/jquery-migrate-3.3.2.min.js" type="text/javascript"></script>
    <script src="/WiseRecruit2/Common/Js/jquery-ui-1.12.1.min.js" type="text/javascript"></script>
    <script type="text/javascript">
	function create_iframe() {
	    //var wrapper = jQuery('#url-wrapper');
	    if (navigator.userAgent.match(/(iPod|iPhone|iPad)/)) {
		//location.href = '/WiseRecruit2/';
		location.assign(location.origin + "/WiseRecruit2/ComFiles/Deloitte/MainHome.aspx");
	    } else {
		var iframe = document.createElement('iframe');
		iframe.frameBorder=0;
		iframe.setAttribute("src", "/WiseRecruit2/");
		document.getElementById("divframe").appendChild(iframe);
	    }
	}
    </script>
    <style type="text/css">
        .scroll-wrapper {
            -webkit-overflow-scrolling: touch;
        }

        .demo-iframe-holder {
            position: fixed;
            right: 0;
            bottom: 0;
            left: 0;
            top: 0;
            -webkit-overflow-scrolling: touch;
        }

		.demo-iframe-holder iframe {
			height: 100%;
			width: 100%;
		}
    </style>	
</head>
<body onload="create_iframe();">
    <div class="scroll-wrapper demo-iframe-holder" id="divframe">
        <!--<iframe src="/WiseRecruit2/" frameborder="0"></iframe>-->
    </div>
</body>
